scenario.en:
const ids = [7, 7, 42, 7, 99, 42];
const seen = new Set(ids);

console.log(seen.size);          // line 1
seen.add(7);
console.log(seen.size);          // line 2
console.log(seen.has(42));       // line 3
console.log(seen.has("42"));     // line 4 — note the quotes

