evidence.en:
const allowed = new Set(["admin", "ops"]);

function canDeploy(userRoles) {
  // userRoles is an array, e.g. ["admin"]
  return allowed.has(userRoles);   // always false — why?
}

canDeploy(["admin"]);   // false ?!

